PH = re.compile(r"%[@d]")

def esc(s):
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")

def main():
    root = os.path.join(os.path.dirname(__file__), "..", "Sources", "Keepit", "Resources")
    en = open(os.path.join(root, "en.lproj", "Localizable.strings"), encoding="utf-8").read()
    keys = re.findall(r'^"((?:\\.|[^"\\])*)" = ', en, re.M)
    keys = [k.replace('\\"', '"').replace("\\n", "\n").replace("\\\\", "\\") for k in keys]
    missing = [k for k in keys if k not in T or k not in T2]
    extra = [k for k in list(T) + list(T2) if k not in keys]
    if missing or extra:
        raise SystemExit(f"missing translations: {missing}\nextra: {extra}")
    import importlib
    tables = [(lang, {k: (T[k] + T2[k])[i] for k in keys}) for i, lang in enumerate(LANGS)]
    for lang, mod in EXTRA_LANGS.items():
        t = importlib.import_module(mod).T
        miss = [k for k in keys if k not in t]
        extra = [k for k in t if k not in keys]
        if miss or extra:
            raise SystemExit(f"[{lang}] missing: {miss}\nextra: {extra}")
        tables.append((lang, t))
    for lang, table in tables:
        lines = [f"/* Keepit — {lang}. Generated by Scripts/gen_strings.py; edit the table there. */", ""]
        for k in keys:
            v = table[k]
            if PH.findall(k) != PH.findall(v):
                raise SystemExit(f"placeholder mismatch [{lang}] {k!r} -> {v!r}")
            lines.append(f'"{esc(k)}" = "{esc(v)}";')
        d = os.path.join(root, f"{lang}.lproj")
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "Localizable.strings"), "w", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")
        print(lang, len(keys), "keys")

if __name__ == "__main__":
    main()
